create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'clinician', created_at timestamptz default now());
create table if not exists public.conditions(id bigint generated by default as identity primary key, number text, condition text not null, chapter_number text, chapter text, printed_page text, source_pages text, symptoms text, signs text, investigations text, treatment text, referral_criteria text, section_text text);
create table if not exists public.medications(id bigint generated by default as identity primary key, drug text not null, formulation text, strength text, level_of_care text, nhis_status text, code text, category text, eml_page text, contraindications text, cautions text);
create table if not exists public.consultations(id uuid primary key default gen_random_uuid(), clinician_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz default now(), patient_input jsonb not null, assessment jsonb not null, source_condition_ids bigint[] default '{}');
alter table public.profiles enable row level security;
alter table public.conditions enable row level security;
alter table public.medications enable row level security;
alter table public.consultations enable row level security;
create policy "authenticated read conditions" on public.conditions for select to authenticated using (true);
create policy "authenticated read medications" on public.medications for select to authenticated using (true);
create policy "own consultations select" on public.consultations for select to authenticated using (auth.uid()=clinician_id);
create policy "own consultations insert" on public.consultations for insert to authenticated with check (auth.uid()=clinician_id);
create policy "own consultations update" on public.consultations for update to authenticated using (auth.uid()=clinician_id) with check (auth.uid()=clinician_id);
create policy "own profile" on public.profiles for select to authenticated using (auth.uid()=id);
create index if not exists conditions_condition_idx on public.conditions using gin(to_tsvector('english',coalesce(condition,'')||' '||coalesce(symptoms,'')||' '||coalesce(signs,'')));
create index if not exists medications_level_idx on public.medications(level_of_care);
